/**
 * The subset of the `codex app-server` v2 protocol that CucCut uses.
 *
 * The authoritative definition is generated by Codex: `codex app-server generate-ts --out <dir>`. This file is checked against codex-cli 0.158.0;
 * `approvalsReviewer`, `model/list`, `turn/steer`, `localImage`, and `codexErrorInfo` in error notifications are checked against the schema exported by 0.159.0.
 * These are all in the stable interface (present in the schema without `--experimental`), so `initialize` does not need to enable `experimentalApi`.
 * Only the fields that are read are copied; unknown fields are ignored and no state is inferred from them.
 */

export type AskForApproval = 'untrusted' | 'on-request' | 'never';
export type SandboxMode = 'read-only' | 'workspace-write' | 'danger-full-access';
/** The full shape of the sandbox override on `turn/start` (0.159.0 `SandboxPolicy`; only the three variants CucCut sends are copied). */
export type SandboxPolicy =
  | { type: 'readOnly'; networkAccess: boolean }
  | { type: 'workspaceWrite'; writableRoots: string[]; networkAccess: boolean; excludeTmpdirEnvVar: boolean; excludeSlashTmp: boolean }
  | { type: 'dangerFullAccess' };
/**
 * Who reviews approval requests (0.159.0 `ApprovalsReviewer`, default `user`). `auto_review` means Codex's review subagent decides whether to approve, based on risk.
 * The schema also has `guardian_subagent`, which CucCut does not use.
 */
export type ApprovalsReviewer = 'user' | 'auto_review';

export interface InitializeParams {
  clientInfo: { name: string; title: string | null; version: string };
  capabilities: { experimentalApi: boolean; requestAttestation: boolean } | null;
}

export interface ThreadStartParams {
  cwd: string;
  approvalPolicy: AskForApproval;
  approvalsReviewer?: ApprovalsReviewer;
  sandbox: SandboxMode;
  model?: string | null;
  developerInstructions?: string | null;
  /** Keys that override `config.toml`, for example `mcp_servers` and `sandbox_workspace_write`. */
  config?: { mcp_servers?: Record<string, CodexMcpServer>; sandbox_workspace_write?: SandboxWorkspaceWrite } | null;
}

/**
 * `config.sandbox_workspace_write`: the details of the `workspace-write` sandbox. By default, besides the working directory, `/tmp` and `$TMPDIR` are also writable;
 * the two `exclude_*` options remove them, and an empty `writable_roots` means no other directories are added.
 */
export interface SandboxWorkspaceWrite {
  writable_roots: string[];
  network_access: boolean;
  exclude_tmpdir_env_var: boolean;
  exclude_slash_tmp: boolean;
}

/**
 * The Streamable HTTP form of `config.mcp_servers.<name>`.
 * `default_tools_approval_mode: 'approve'`: calls are no longer asked about through Codex; permissions are checked by the Runtime per task (architecture design §3.5).
 * `tool_timeout_sec`: the limit on one tool call (Codex default 60 seconds); CucCut's tools may be waiting for user approval, see `MCP_TOOL_CALL_TIMEOUT_MS`.
 */
export interface CodexMcpServer {
  url: string;
  http_headers: Record<string, string>;
  default_tools_approval_mode: 'auto' | 'prompt' | 'approve';
  /** The longest time to wait for one tool call, in seconds; Codex default is 60. */
  tool_timeout_sec?: number;
}

export interface ThreadResumeParams extends ThreadStartParams {
  threadId: string;
  excludeTurns?: boolean;
}

export interface ThreadStartResponse {
  thread: { id: string };
  model: string;
}

/** One piece of user input (a subset of 0.159.0 `UserInput`). `localImage` is the path of a local image file, which Codex reads itself. */
export type CodexUserInput = { type: 'text'; text: string; text_elements: [] } | { type: 'localImage'; path: string };

export interface TurnStartParams {
  threadId: string;
  input: CodexUserInput[];
  /** The following fields apply to this turn and later turns (access mode, model, and reasoning effort change with the session settings). */
  approvalPolicy?: AskForApproval;
  approvalsReviewer?: ApprovalsReviewer;
  sandboxPolicy?: SandboxPolicy;
  model?: string | null;
  effort?: string | null;
}

export interface TurnStartResponse {
  turn: CodexTurn;
}

/**
 * `turn/steer`: inserts input into the turn that is running. `expectedTurnId` is a precondition: the request fails if it does not match the current active turn
 * (`-32600`, `expected active turn id ... but found ...`; with no active turn it is `no active turn to steer`).
 */
export interface TurnSteerParams {
  threadId: string;
  input: CodexUserInput[];
  expectedTurnId: string;
}

export interface TurnSteerResponse {
  turnId: string;
}

/**
 * The structured cause inside a turn error (0.159.0 `CodexErrorInfo`). Strings are unit variants; objects are variants that carry an HTTP status;
 * there is no "model does not exist" entry: an upstream 404 falls under `other`, and only the raw text can be checked.
 */
export type CodexErrorInfo =
  | 'contextWindowExceeded'
  | 'sessionBudgetExceeded'
  | 'usageLimitExceeded'
  | 'rateLimitExceeded'
  | 'flexUnavailable'
  | 'serverOverloaded'
  | 'cyberPolicy'
  | 'misalignmentPolicyViolation'
  | 'tooManyDenials'
  | 'internalServerError'
  | 'unauthorized'
  | 'badRequest'
  | 'threadRollbackFailed'
  | 'sandboxError'
  | 'other'
  | { httpConnectionFailed: { httpStatusCode: number | null } }
  | { responseStreamConnectionFailed: { httpStatusCode: number | null } }
  | { responseStreamDisconnected: { httpStatusCode: number | null } }
  | { responseTooManyFailedAttempts: { httpStatusCode: number | null } }
  | { activeTurnNotSteerable: { turnKind: 'review' | 'compact' } };

export interface CodexTurnError {
  message: string;
  codexErrorInfo?: CodexErrorInfo | null;
  additionalDetails: string | null;
}

/** `error` notification. When `willRetry` is true, Codex retries on its own and the turn continues; when false, the `turn/completed` that follows is `failed` and carries the same error. */
export interface ErrorNotification {
  error: CodexTurnError;
  willRetry: boolean;
  threadId: string;
  turnId: string;
}

export interface CodexTurn {
  id: string;
  status: 'completed' | 'interrupted' | 'failed' | 'inProgress';
  error: CodexTurnError | null;
}

/** `model/list` (0.159.0 `ModelListParams`). `includeHidden`: also list the models hidden from the default picker. */
export interface ModelListParams {
  cursor?: string | null;
  limit?: number | null;
  includeHidden?: boolean | null;
}

export interface ModelListResponse {
  data: CodexModel[];
  /** Cursor for the next page; null means there are no more. */
  nextCursor: string | null;
}

/** The fields CucCut reads from 0.159.0 `Model`. In the current catalog `id` and `model` are the same; turn/start's `model` uses `id`. */
export interface CodexModel {
  id: string;
  model?: string;
  displayName: string;
  description: string;
  hidden: boolean;
  isDefault: boolean;
  supportedReasoningEfforts: Array<{ reasoningEffort: string; description: string }>;
  defaultReasoningEffort: string;
}

type ExecStatus = 'inProgress' | 'completed' | 'failed' | 'declined';

export type CodexThreadItem =
  | { type: 'userMessage'; id: string; content: Array<{ type: string; text?: string }> }
  | { type: 'agentMessage'; id: string; text: string }
  | { type: 'plan'; id: string; text: string }
  | { type: 'reasoning'; id: string; summary: string[]; content: string[] }
  | {
      type: 'commandExecution';
      id: string;
      command: string;
      cwd: string;
      status: ExecStatus;
      aggregatedOutput: string | null;
      exitCode: number | null;
      durationMs: number | null;
    }
  | {
      type: 'fileChange';
      id: string;
      changes: Array<{ path: string; kind: { type: 'add' | 'delete' | 'update' }; diff: string }>;
      status: ExecStatus;
    }
  | {
      type: 'mcpToolCall';
      id: string;
      server: string;
      tool: string;
      status: 'inProgress' | 'completed' | 'failed';
      arguments: unknown;
      result: { content: unknown[] } | null;
      error: { message: string } | null;
      durationMs: number | null;
    }
  | {
      type: 'dynamicToolCall';
      id: string;
      tool: string;
      status: 'inProgress' | 'completed' | 'failed';
      durationMs: number | null;
    }
  | { type: 'webSearch'; id: string; query: string }
  | { type: string; id: string };

export interface CommandApprovalParams {
  threadId: string;
  turnId: string;
  itemId: string;
  approvalId?: string | null;
  reason?: string | null;
  command?: string | null;
  cwd?: string | null;
}

export interface FileChangeApprovalParams {
  threadId: string;
  turnId: string;
  itemId: string;
  reason?: string | null;
  grantRoot?: string | null;
}

export type CodexApprovalDecision = 'accept' | 'acceptForSession' | 'decline' | 'cancel';
